(* [comment removed for export] *)
Lemma das_loop : forall L (cur kti kid kname : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem),
  SvcChain m cur L -> L <> [] ->
  Forall (fun e => keys_match kti kid kname e = false) L ->
  (kti <> 0 -> ro_cells rsegs m (kti + 8) [C8 (wz kname)]) ->
  0 <= kti < 2^64 -> 0 <= kid < 2^64 -> 0 <= kname < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (fun ms' => exists a3' a4',
               ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz 0) (wz kti) (wz kid) a3' a4' a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                        F (Z_to_bv 64 P_DAS_SCAN_DONE) fc None m (seg_rom rsegs))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz cur) (wz kti) (wz kid) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_DAS_LOOP) fc None m (seg_rom rsegs)).
