(* [comment removed for export] *)
Definition das_W (lo : Z) (sp : word) (r svc : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (r, r + SZ_REG); (svc, svc + SZ_SVC)]%Z.

Definition do_add_service_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (r svc owner first kti kid lo : Z) (S0 : svch) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (das_W lo sp r svc) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ Registry LB m' r owner svc 0
    /\ rw_cells rsegs m' svc (SvcHdrCells (mkSVC (sv_vptr S0) kti kid owner first (sv_destroy S0))).

Definition do_add_service_stmt : Prop :=
  forall (r K svc lo : Z) (LB : list block) (L : list svce) (S0 : svch) (owner first kti kid kname : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  Registry LB m r owner first 0 ->
  rw_cells rsegs m svc (SvcHdrCells S0) -> svch_ok S0 -> sv_owner S0 = owner -> sv_destroy S0 <> 0 ->
  ro_cells rsegs m K [C8 (wz kti); C8 (wz kid)] -> 0 <= kti < 2^64 -> 0 <= kid < 2^64 -> 0 <= kname < 2^64 ->
  (kti <> 0 -> ro_cells rsegs m (kti + 8) [C8 (wz kname)] /\ 0x10000 <= kti + 8 /\ kti + 16 <= 0xb4000) ->
  SvcChain m first L -> Forall (fun e => keys_match kti kid kname e = false) L ->
  Forall (svce_off (das_W lo sp r svc)) L ->
  bv_unsigned sp <= K -> K + 16 <= 2^64 ->
  r + NEWSZ_REG <= lo -> (r + SZ_REG <= 0x10000 \/ 0xb4000 <= r) ->
  svc + SZ_SVC <= lo -> (svc + SZ_SVC <= 0x10000 \/ 0xb4000 <= svc) ->
  (r + NEWSZ_REG <= svc \/ svc + SZ_SVC <= r) ->
  stk rsegs m lo (bv_unsigned sp) -> lo + DAS_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (do_add_service_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB r svc owner first kti kid lo S0 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz r) (wz K) (wz svc) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_DO_ADD_SERVICE) fc None m (seg_rom rsegs)).
Scheme kc__5 := Elimination for Corelib.Init.Logic.ex Sort Prop.

