Definition P_DUS_LOOP1 : Z := 0x2e7c8.
Definition P_DUS_SCAN1_NONE : Z := 0x2e7f4.
Definition P_DUS_FOUND : Z := 0x2e890.
Definition P_DUS_LOOP2 : Z := 0x2e83c.
Definition P_DUS_SCAN2_NONE : Z := 0x2e868.
Definition DUS_STACK : Z := 80 + MUTEX_UNLOCK_STACK.

Lemma keys_match_true_id : forall kti kid kname a S nm,
  sv_id S <> 0 -> sv_id S = kid -> keys_match kti kid kname (mkSE a S nm) = true.
Proof.
  intros kti kid kname a S nm H1 H2. unfold keys_match. cbn [se_hdr se_tiname].
  rewrite (proj2 (Z.eqb_neq _ _) H1), (proj2 (Z.eqb_eq _ _) H2). reflexivity.
Qed.
Lemma keys_match_true_ti : forall kti kid kname a S nm,
  sv_ti S <> 0 -> kti <> 0 -> nm = kname -> keys_match kti kid kname (mkSE a S nm) = true.
Proof.
  intros kti kid kname a S nm H1 H2 H3. unfold keys_match. cbn [se_hdr se_tiname].
  rewrite (proj2 (Z.eqb_neq _ _) H1), (proj2 (Z.eqb_neq _ _) H2), (proj2 (Z.eqb_eq _ _) H3). cbn. apply orb_true_r.
Qed.
Lemma keys_match_false_intro : forall kti kid kname a S nm,
  (sv_id S = 0 \/ sv_id S <> kid) -> (sv_ti S = 0 \/ kti = 0 \/ nm <> kname) ->
  keys_match kti kid kname (mkSE a S nm) = false.
Proof.
  intros kti kid kname a S nm H1 H2. unfold keys_match. cbn [se_hdr se_tiname].
  apply orb_false_iff. split.
  - apply andb_false_iff. destruct H1 as [H1|H1].
    + left. rewrite (proj2 (Z.eqb_eq _ _) H1). reflexivity.
    + right. apply Z.eqb_neq. exact H1.
  - destruct H2 as [H2|[H2|H2]].
    + rewrite (proj2 (Z.eqb_eq _ _) H2). reflexivity.
    + rewrite (proj2 (Z.eqb_eq _ _) H2). cbn. rewrite andb_false_r. reflexivity.
    + rewrite (proj2 (Z.eqb_neq _ _) H2). apply andb_false_r.
Qed.

