Lemma dus_loop1 : forall L (cur kti kid kname : Z)
    ra sp gp tp t0 t1 t2 s0 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem),
  SvcChain m cur L -> L <> [] ->
  (kti <> 0 -> ro_cells rsegs m (kti + 8) [C8 (wz kname)]) ->
  0 <= kti < 2^64 -> 0 <= kid < 2^64 -> 0 <= kname < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (fun ms' => exists a2' a3',
               ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (wz (find_svc kti kid kname L)) (wz kti) (wz kid) a2' a3' a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                        F (Z_to_bv 64 (if find_svc kti kid kname L =? 0 then P_DUS_SCAN1_NONE else P_DUS_FOUND)) fc None m (seg_rom rsegs))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (wz cur) (wz kti) (wz kid) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_DUS_LOOP1) fc None m (seg_rom rsegs)).
