(* [comment removed for export] *)
Definition dusf_W (lo : Z) (sp : word) (r : Z) : list (Z * Z) := [(lo, bv_unsigned sp); (r + O_REG_MUTEX, r + O_REG_MUTEX + 40)]%Z.

Definition do_use_service_found_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (r owner first fsv lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz fsv) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (dusf_W lo sp r) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ Registry LB m' r owner first 0.

Definition do_use_service_found_stmt : Prop :=
  forall (r K fsv lo : Z) (LB : list block) (L : list svce) (owner first kti kid kname : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  Registry LB m r owner first 0 ->
  ro_cells rsegs m K [C8 (wz kti); C8 (wz kid)] -> 0 <= kti < 2^64 -> 0 <= kid < 2^64 -> 0 <= kname < 2^64 ->
  (kti <> 0 -> ro_cells rsegs m (kti + 8) [C8 (wz kname)] /\ 0x10000 <= kti + 8 /\ kti + 16 <= 0xb4000) ->
  SvcChain m first L -> find_svc kti kid kname L = fsv -> fsv <> 0 ->
  Forall (svce_off (dusf_W lo sp r)) L ->
  bv_unsigned sp <= K -> K + 16 <= 2^64 ->
  r + NEWSZ_REG <= lo -> (r + SZ_REG <= 0x10000 \/ 0xb4000 <= r) ->
  stk rsegs m lo (bv_unsigned sp) -> lo + DUS_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (do_use_service_found_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB r owner first fsv lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz r) (wz K) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_DO_USE_SERVICE) fc None m (seg_rom rsegs)).

