Definition P_MSC_RET1 : Z := 0x2c098.
Definition MAKE_SVC_CONFIG_STACK : Z := 64 + ALLOCATE_STACK.

Lemma Registry_cons_LB : forall LB b m r owner first lk, Registry LB m r owner first lk -> Registry (b :: LB) m r owner first lk.
Proof.
  intros LB b m r owner first lk (p & j0 & j7 & IN & R). exists p, j0, j7. split; [right; exact IN| exact R].
Qed.

Lemma XS_tiname_config : forall m, XStatics m -> ro_cells rsegs m (L_TYPEID_CONFIG + 8) [C8 (wz TI_NAME_CONFIG)].
