(* [comment removed for export] *)
Definition msc_W (lo : Z) (sp : word) (A r : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (A, A + SZ_CFG); (r, r + SZ_REG)]%Z.

Definition cfg_hdr (ioc : Z) : svch := mkSVC VP_CONFIG_SVC L_TYPEID_CONFIG 0 ioc 0 P_DESTROY_ALLOC_CONFIG.

Definition msc_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (A r ioc lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j4,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (msc_W lo sp A r) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' A (SvcHdrCells (cfg_hdr ioc) ++ [C4 (wz 4294967295); CB 4 j4])
    /\ Registry LB m' r ioc A 0
    /\ XStatics m'.

Lemma msc_segB : forall sp gp tp t0 t1 t2 s0x a1 a2 a3 a4 a5 a6 a7 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (LB : list block) (A r hintp ioc lo : Z) (ra s0 s1 s2 s3 : word) (junkF junkB : list byte),
  rw_cells rsegs m (bv_unsigned sp + -64) [CB 24 junkF; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells rsegs m A [CB 56 junkB] ->
  ro_cells rsegs m hintp [C4 (wz 4294967295)] ->
