(* [comment removed for export] *)
Definition P_DUSC_RET : Z := 0x2e80c.

Definition dusc_segA_post (sp gp tp t0 t1 t2 a6 a7 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (r K ctx own first lo : Z) (ra s0 s1 s2 s3 s4 s5 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a2 a3 a4 a5 m' j0 j7,
    ms' = MS (mkR (Z_to_bv 64 P_DUSC_RET) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
                  (Z_to_bv 64 (r + 8)) (Z_to_bv 64 0) (Z_to_bv 64 ctx) (Z_to_bv 64 own) a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 r) (Z_to_bv 64 K) (Z_to_bv 64 P_CREATE_SSVC) (Z_to_bv 64 own) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_CREATE_SSVC) fc None m' (seg_rom rsegs)
    /\ munch (dusf_W lo sp r) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -80)
    /\ rw_cells rsegs m' (bv_unsigned sp + -80)
         [CB 8 j0; C8 (Z_to_bv 64 (r + 8)); C1 (b8 0); CB 7 j7; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ Registry LB m' r ctx first 0.

Lemma dusc_segA : forall (r K own lo : Z) (LB : list block) (L : list svce) (ctx first kti kid kname : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  Registry LB m r ctx first 0 ->
  ro_cells rsegs m K [C8 (wz kti); C8 (wz kid)] -> 0 <= kti < 2^64 -> 0 <= kid < 2^64 -> 0 <= kname < 2^64 ->
  (kti <> 0 -> ro_cells rsegs m (kti + 8) [C8 (wz kname)] /\ 0x10000 <= kti + 8 /\ kti + 16 <= 0xb4000) ->
  SvcChain m first L -> find_svc kti kid kname L = 0 ->
  Forall (svce_off (dusf_W lo sp r)) L ->
  bv_unsigned sp <= K -> K + 16 <= 2^64 ->
  r + NEWSZ_REG <= lo -> (r + SZ_REG <= 0x10000 \/ 0xb4000 <= r) ->
  0 <= ctx < 2^64 -> 0 <= own < 2^64 ->
  stk rsegs m lo (bv_unsigned sp) -> lo + DUS_STACK <= bv_unsigned sp -> hceil <= lo ->
  mem_inv rsegs m ->
  evt rsegs (dusc_segA_post sp gp tp t0 t1 t2 a6 a7 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc LB r K ctx own first lo ra s0 s1 s2 s3 s4 s5 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz r) (wz K) (wz P_CREATE_SSVC) (wz own) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_DO_USE_SERVICE) fc None m (seg_rom rsegs)).
