Lemma AllocImpl_xpres : forall LB SP X m m' a,
  AllocImpl LB m a -> xpres LB SP X m m' -> Forall (fun iv : Z * Z => a + SZ_ALLOCIMPL <= fst iv \/ snd iv <= a) X ->
  AllocImpl LB m' a.
Proof.
  intros LB SP X m m' a (p & junk & IN & C) XP FX. exists p, junk. split; [exact IN|].
  eapply xpres_rw_cells; [exact XP| exact C|]. split.
  - right; right. exists (p, a, SZ_ALLOCIMPL). split; [exact IN| cbn; unfold SZ_ALLOCIMPL; lia].
  - eapply Forall_impl; [| exact FX]. intros [lo hi] K; cbn in *; unfold SZ_ALLOCIMPL in *; lia.
Qed.

Lemma ro_cells_xpres : forall LB SP X m m' A cs,
  xpres LB SP X m m' -> ro_cells rsegs m A cs -> xclient_range LB SP X A (Z.of_nat (cells_size cs)) -> ro_cells rsegs m' A cs.
Proof.
  intros LB SP X m m' A cs XP [Hwf HB] HR. split; [exact Hwf|].
  eapply xpres_bytes_at; eauto. rewrite cells_bytes_length by fast_assumption. exact HR.
Qed.

