Definition P_AOR_RET1 : Z := 0x2d5c0.
Definition ALLOC_OBJ_REGISTRY_STACK : Z := 144 + ALLOCATE_STACK.

Lemma XS_system_cat : forall m, XStatics m ->
  rw_cells rsegs m 0x80870 [C8 (Z_to_bv 64 W_SYSTEM_CAT_VPTR); C8 (Z_to_bv 64 W_SYSTEM_CAT_ID)].
Proof.
  intros m XS. destruct XS as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & H0 & _). exact H0.
Qed.

(* [comment removed for export] *)
Lemma le8_zero_split : le8 (Z_to_bv 64 0) = le4 (Z_to_bv 64 0) ++ le4 (Z_to_bv 64 0).
Proof. vm_compute. reflexivity. Qed.
Lemma rw_cells_C8zero_split : forall m A pre post,
  rw_cells rsegs m A (pre ++ C8 (Z_to_bv 64 0) :: post) ->
  rw_cells rsegs m A (pre ++ C4 (Z_to_bv 64 0) :: C4 (Z_to_bv 64 0) :: post).
Proof.
  intros m A pre post RC. pose proof RC as [[WF _] _]. apply cells_wf_app in WF. destruct WF as [W1 [_ W3]].
  eapply rw_cells_recells; [exact RC| | |].
  - apply cells_wf_app. split; [exact W1|]. cbn. split; [exact I|]. split; [exact I|]. exact W3.
  - rewrite !cells_bytes_app. cbn [cells_bytes cbytes]. rewrite le8_zero_split, <- app_assoc. reflexivity.
  - rewrite !cells_size_app. reflexivity.
Qed.

(* [comment removed for export] *)
Definition aor_segA_post (sp gp tp t0 t1 t2 a4 a5 a6 a7 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (ioc allocb lo : Z) (ra s0 s1 s2 s3 s4 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a3 m' junk,
    ms' = MS (mkR (Z_to_bv 64 P_AOR_RET1) (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2
                  (Z_to_bv 64 allocb) s1 (Z_to_bv 64 allocb) (Z_to_bv 64 64) (Z_to_bv 64 8) a3 a4 a5 a6 a7
                  (Z_to_bv 64 ioc) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_ALLOCIMPL_ALLOCATE) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -144)
    /\ rw_cells rsegs m' (bv_unsigned sp + -144) [CB 96 junk; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Lemma aor_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (AT ioc allocb lo : Z) (jal : list byte),
  ro_cells rsegs m AT [C8 (wz allocb)] ->
  rw_cells rsegs m allocb [C8 (wz VP_ALLOCIMPL); CB 8 jal] -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 144 <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp <= AT -> AT + 8 <= 2^64 -> allocb + SZ_ALLOCIMPL <= lo ->
  mem_inv rsegs m ->
  evt rsegs (aor_segA_post sp gp tp t0 t1 t2 a4 a5 a6 a7 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc ioc allocb lo ra s0 s1 s2 s3 s4 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 AT) (Z_to_bv 64 ioc) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
