(* [comment removed for export] *)
Definition aor_W (lo : Z) (sp : word) (A : Z) : list (Z * Z) := [(lo, bv_unsigned sp); (A, A + SZ_REG)]%Z.

Definition aor_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A ioc lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j0,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (aor_W lo sp A) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' A [CB 8 j0]
    /\ PMutex m' (A + O_REG_MUTEX) 0
    /\ rw_cells rsegs m' (A + O_REG_OWNER) [C8 (wz ioc); C8 (wz 0)]
    /\ CanaryReads m' /\ XStatics m'.

Lemma aor_segB : forall sp gp tp t0 t1 t2 s1x a1 a2 a3 a4 a5 a6 a7 s3x s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (A ioc allocb lo : Z) (ra s0 s1 s2 s3 s4 : word) (junkF junkB : list byte),
  rw_cells rsegs m (bv_unsigned sp + -144) [CB 96 junkF; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells rsegs m A [CB 64 junkB] ->
  XStatics m -> CanaryReads m ->
  stk rsegs m lo (bv_unsigned sp + -144) -> lo + 144 + MUTEX_INIT_STACK <= bv_unsigned sp -> hceil <= lo ->
  A + NEWSZ_REG <= lo -> (A + NEWSZ_REG <= 0x10000 \/ 0xb4000 <= A) -> 0 < A -> A mod 16 = 0 ->
  0 <= ioc < 2^64 ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (aor_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc A ioc lo m)
    (MS (mkR (Z_to_bv 64 P_AOR_RET1) (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2
             (Z_to_bv 64 allocb) s1x (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 ioc) s3x s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_AOR_RET1) fc None m (seg_rom rsegs)).
