(* [comment removed for export] *)
Lemma SvcChain_xpres : forall LB SP X m m' first L,
  SvcChain m first L -> xpres LB SP X m m' ->
  Forall (fun e => xclient_range LB SP X (se_addr e) 48) L ->
  Forall (fun iv : Z * Z => 0x7f000 <= fst iv \/ snd iv <= 0x7a000) X ->
  SvcChain m' first L.
Proof.
  intros LB SP X m m' first L. revert first. induction L as [|e L IH]; intros first CH XP XL FX; [exact CH|].
  cbn in CH |- *. destruct CH as (E & POS & HI & HD & OK & TI & CH').
  pose proof (Forall_inv XL) as X1.
  split; [exact E|]. split; [exact POS|]. split; [exact HI|].
  split. { eapply ro_cells_xpres; [exact XP| exact HD|]. cbn [cells_size csize Nat.add SvcHdrCells]. exact X1. }
  split; [exact OK|]. split.
  { intros NZ. destruct (TI NZ) as (RO & R & LO' & HI'). split; [| split; [exact R| split; [exact LO'| exact HI']]].
    eapply ro_cells_xpres; [exact XP| exact RO|]. cbn [cells_size csize Nat.add]. split.
    - right; left. unfold RLIBC, RCTX, RERRNO, RSSP_GUARD, RGOT_SSP, RVMLOCK. lia.
    - eapply Forall_impl; [| exact FX]. intros [lo hi] K; cbn in *; lia. }
  apply IH; [exact CH'| exact XP| exact (Forall_inv_tail XL)| exact FX].
Qed.

Lemma find_svc_none : forall kti kid kname L,
  Forall (fun e => keys_match kti kid kname e = false) L -> find_svc kti kid kname L = 0.
Proof.
  intros kti kid kname L NM. induction L as [|e L IH]; [reflexivity|]. cbn. rewrite (Forall_inv NM). apply IH. exact (Forall_inv_tail NM).
Qed.

(* [comment removed for export] *)
Definition svce_inblock (LB : list block) (e : svce) : Prop :=
  exists b, In b LB /\ blk_addr b <= se_addr e /\ se_addr e + 48 <= blk_addr b + blk_size b.

(* [comment removed for export] *)
Definition sep (a n b k : Z) : Prop := a + n <= b \/ b + k <= a.

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  (* [comment removed for export] *)
  Hypothesis RHEAP_canary : forall s LB m, hs_RHEAP H s LB m -> CanaryReads m.

  Definition alloc_obj_registry_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (ioc allocb lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (p : bptr) (A : Z),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ rblock_range A NEWSZ_REG /\ hs_RHEAP H s' ((p, A, NEWSZ_REG) :: LB) m'
      /\ Registry ((p, A, NEWSZ_REG) :: LB) m' A ioc 0 0
      /\ AllocImpl ((p, A, NEWSZ_REG) :: LB) m' allocb
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) [] m m'.

  Definition alloc_obj_registry_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (AT ioc allocb lo B : Z) (errv : word),
      a0 = Z_to_bv 64 AT -> a1 = Z_to_bv 64 ioc ->
      ro_cells rsegs m AT [C8 (wz allocb)] -> bv_unsigned sp <= AT -> AT + 8 <= 2^64 -> 0 <= ioc < 2^64 ->
      AllocImpl LB m allocb -> XStatics m ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + NEWSZ_REG <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - ALLOC_OBJ_REGISTRY_STACK ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned ra mod 2 = 0 ->
      hs_SR H (alloc_obj_registry_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB ioc allocb lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_ALLOC_OBJ_REGISTRY) fc None m (seg_rom rsegs)) mo).
Scheme kc__7 := Elimination for LinuxProcessSemantics.LinuxProcessSem.Run.config Sort Prop.
Scheme kc__8 := Elimination for Corelib.Init.Logic.or Sort Prop.

  Lemma alloc_obj_registry_spec : alloc_obj_registry_stmt.
