  (* [comment removed for export] *)
  (* [comment removed for export] *)
  Definition CREATE_SSVC_STACK : Z := 16 + 32 + MAKE_SHARED_IMPL_STACK.

  Definition ssvc_hdr0 (own : Z) : svch := mkSVC VP_SSVC 0 0 own 0 P_DESTROY_ALLOC_SSVC.

  Definition create_ssvc_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (own allocb lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (p1 : bptr) (v : Z) (p2 : bptr) (q : Z) j7,
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 v) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ rblock_range v NEWSZ_SSVC /\ rblock_range q SZ_SPCI_IMPL
      /\ hs_RHEAP H s' ((p2, q, SZ_SPCI_IMPL) :: (p1, v, NEWSZ_SSVC) :: LB) m'
      /\ rw_cells rsegs m' v (SvcHdrCells (ssvc_hdr0 own) ++ [C8 (wz (q + O_SPC_STORAGE)); C8 (wz q)] ++ CookieCells j7)
      /\ ImplBlock ((p2, q, SZ_SPCI_IMPL) :: (p1, v, NEWSZ_SSVC) :: LB) m' q (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 1) 0 0 [] 0)
      /\ AllocImpl ((p2, q, SZ_SPCI_IMPL) :: (p1, v, NEWSZ_SSVC) :: LB) m' allocb
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) [] m m'.

  Definition create_ssvc_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (ctx own allocb lo B : Z) (errv : word),
      a0 = Z_to_bv 64 ctx -> a1 = Z_to_bv 64 own ->
      ro_cells rsegs m ctx [C8 (wz allocb)] -> bv_unsigned sp <= ctx -> ctx + 8 <= 2^64 -> 0 <= own < 2^64 ->
      AllocImpl LB m allocb -> XStatics m ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + NEWSZ_SSVC + SZ_SPCI_IMPL <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 2 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - CREATE_SSVC_STACK ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned ra mod 2 = 0 ->
      hs_SR H (create_ssvc_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB own allocb lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_CREATE_SSVC) fc None m (seg_rom rsegs)) mo).

  Hypothesis CREATE : create_ssvc_stmt.

  (* [comment removed for export] *)
  Definition DUSC_STACK : Z := 80 + CREATE_SSVC_STACK.

  Definition do_use_service_create_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (r ctx own first kti kid allocb lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (p1 : bptr) (v : Z) (p2 : bptr) (q : Z),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 v) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ rblock_range v NEWSZ_SSVC /\ rblock_range q SZ_SPCI_IMPL
      /\ hs_RHEAP H s' ((p2, q, SZ_SPCI_IMPL) :: (p1, v, NEWSZ_SSVC) :: LB) m'
      /\ Registry ((p2, q, SZ_SPCI_IMPL) :: (p1, v, NEWSZ_SSVC) :: LB) m' r ctx v 0
      /\ StreamSvc ((p2, q, SZ_SPCI_IMPL) :: (p1, v, NEWSZ_SSVC) :: LB) m' v (mkSVC VP_SSVC kti kid own first P_DESTROY_ALLOC_SSVC) q
      /\ ImplBlock ((p2, q, SZ_SPCI_IMPL) :: (p1, v, NEWSZ_SSVC) :: LB) m' q (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 1) 0 0 [] 0)
      /\ AllocImpl ((p2, q, SZ_SPCI_IMPL) :: (p1, v, NEWSZ_SSVC) :: LB) m' allocb
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) [(r, r + NEWSZ_REG)] m m'.

  Definition do_use_service_create_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (L : list svce) (r K ctx own first kti kid kname allocb lo B : Z) (errv : word),
      a0 = Z_to_bv 64 r -> a1 = Z_to_bv 64 K -> a2 = Z_to_bv 64 P_CREATE_SSVC -> a3 = Z_to_bv 64 own ->
      Registry LB m r ctx first 0 ->
      ro_cells rsegs m ctx [C8 (wz allocb)] -> bv_unsigned sp <= ctx -> ctx + 8 <= 2^64 -> 0 <= own < 2^64 ->
      AllocImpl LB m allocb -> XStatics m ->
      ro_cells rsegs m K [C8 (wz kti); C8 (wz kid)] -> bv_unsigned sp <= K -> K + 16 <= 2^64 ->
      0 <= kti < 2^64 -> 0 <= kid < 2^64 -> 0 <= kname < 2^64 ->
      (kti <> 0 -> ro_cells rsegs m (kti + 8) [C8 (wz kname)] /\ 0x7a000 <= kti + 8 /\ kti + 16 <= 0x7f000) ->
      SvcChain m first L -> Forall (fun e => keys_match kti kid kname e = false) L ->
      Forall (svce_inblock LB) L -> Forall (fun e => se_addr e + 48 <= r \/ r + NEWSZ_REG <= se_addr e) L ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + NEWSZ_SSVC + SZ_SPCI_IMPL <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 2 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - DUSC_STACK ->
